import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const databasePath = process.env.DB_PATH || join(root, 'workboard.sqlite');
const db = new DatabaseSync(databasePath);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
  )
`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const getProject = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
db.exec(`
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  )
`);
db.exec('PRAGMA foreign_keys = ON');
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived,
  COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id GROUP BY p.id ORDER BY p.id`);
const setArchived = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');

function sendJson(res, status, value) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(value));
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    sendJson(res, 200, { status: 'ok' });
    return;
  }
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    sendJson(res, 200, listProjects.all());
    return;
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    try {
      let body = '';
      for await (const chunk of req) body += chunk;
      const name = JSON.parse(body).name;
      if (typeof name !== 'string' || !name.trim()) {
        sendJson(res, 400, { error: 'Project name is required' });
        return;
      }
      const result = createProject.run(name.trim());
      sendJson(res, 201, { id: Number(result.lastInsertRowid), name: name.trim() });
    } catch {
      sendJson(res, 400, { error: 'Invalid request' });
    }
    return;
  }
  const renameMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (req.method === 'PATCH' && renameMatch) {
    try {
      let body = '';
      for await (const chunk of req) body += chunk;
      const name = JSON.parse(body).name;
      if (typeof name !== 'string' || !name.trim()) { sendJson(res, 400, { error: 'Project name is required' }); return; }
      const id = Number(renameMatch[1]);
      const project = getProject.get(id);
      if (!project) { sendJson(res, 404, { error: 'Project not found' }); return; }
      if (project.archived) { sendJson(res, 409, { error: 'Archived projects cannot be renamed' }); return; }
      const trimmedName = name.trim();
      renameProject.run(trimmedName, id);
      sendJson(res, 200, { id, name: trimmedName });
    } catch { sendJson(res, 400, { error: 'Invalid request' }); }
    return;
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/archive$/);
  if (req.method === 'PATCH' && archiveMatch) {
    try {
      let body = '';
      for await (const chunk of req) body += chunk;
      const { archived } = JSON.parse(body);
      if (typeof archived !== 'boolean') { sendJson(res, 400, { error: 'Invalid archive state' }); return; }
      const project = getProject.get(Number(archiveMatch[1]));
      if (!project) { sendJson(res, 404, { error: 'Project not found' }); return; }
      setArchived.run(archived ? 1 : 0, Number(archiveMatch[1]));
      sendJson(res, 200, { archived });
    } catch { sendJson(res, 400, { error: 'Invalid request' }); }
    return;
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (req.method === 'GET' && tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!getProject.get(projectId)) { sendJson(res, 404, { error: 'Project not found' }); return; }
    sendJson(res, 200, listTasks.all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
    return;
  }
  if (req.method === 'POST' && tasksMatch) {
    try {
      let body = '';
      for await (const chunk of req) body += chunk;
      const title = JSON.parse(body).title;
      const projectId = Number(tasksMatch[1]);
      if (typeof title !== 'string' || !title.trim()) { sendJson(res, 400, { error: 'Task title is required' }); return; }
      const project = getProject.get(projectId);
      if (!project) { sendJson(res, 404, { error: 'Project not found' }); return; }
      if (project.archived) { sendJson(res, 409, { error: 'Archived projects cannot have tasks' }); return; }
      const result = createTask.run(projectId, title.trim());
      sendJson(res, 201, { id: Number(result.lastInsertRowid), projectId, title: title.trim(), completed: false });
    } catch { sendJson(res, 400, { error: 'Invalid request' }); }
    return;
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (req.method === 'PATCH' && taskMatch) {
    try {
      let body = '';
      for await (const chunk of req) body += chunk;
      const payload = JSON.parse(body);
      const projectId = Number(taskMatch[1]);
      const taskId = Number(taskMatch[2]);
      const project = getProject.get(projectId);
      if (!project) { sendJson(res, 404, { error: 'Project not found' }); return; }
      if (project.archived) { sendJson(res, 409, { error: 'Archived project tasks are read-only' }); return; }
      if (typeof payload.completed === 'boolean') {
        const result = updateTask.run(payload.completed ? 1 : 0, taskId, projectId);
        if (!result.changes) { sendJson(res, 404, { error: 'Task not found' }); return; }
        sendJson(res, 200, { completed: payload.completed });
        return;
      }
      if (typeof payload.title !== 'string' || !payload.title.trim()) { sendJson(res, 400, { error: 'Task title is required' }); return; }
      const title = payload.title.trim();
      const result = renameTask.run(title, taskId, projectId);
      if (!result.changes) { sendJson(res, 404, { error: 'Task not found' }); return; }
      sendJson(res, 200, { id: taskId, projectId, title });
    } catch { sendJson(res, 400, { error: 'Invalid request' }); }
    return;
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (req.method === 'GET' && projectMatch) {
    const project = getProject.get(Number(projectMatch[1]));
    if (project) sendJson(res, 200, project);
    else sendJson(res, 404, { error: 'Project not found' });
    return;
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    try {
      const html = await readFile(join(root, 'public', 'index.html'));
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(html);
    } catch {
      sendJson(res, 500, { error: 'Application unavailable' });
    }
    return;
  }
  sendJson(res, 404, { error: 'Not found' });
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');

function shutdown() {
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

